#!/usr/bin/env Rscript
source(file.path(Sys.getenv('DISCO_RUN_MODULE'),'code/export_r_sources.R'))
suppressPackageStartupMessages({library(ggpubr);library(ggthemes);library(ggsci);library(dplyr);library(MASS);library(ggpointdensity);library(survminer)})
block<-function(src,lo,hi,e){
 for(ex in parse(text=readLines(src,warn=FALSE)[lo:hi])){
  v<-withVisible(eval(ex,e));if(inherits(v$value,'ggplot'))e$.last_plot<-v$value
 }
}
ctx<-function(){e<-new.env(parent=globalenv());e$pdf<-e$cairo_pdf<-function(...)invisible(NULL);e$dev.off<-function(...)invisible(NULL);e}
plotlayers<-function(panel,name,p,src,def,privacy='aggregate_public_candidate',complete=TRUE){
 b<-ggplot_build(p)
 for(i in seq_along(b$data))if(nrow(b$data[[i]])>0)emit(panel,paste0(name,'_layer',i),b$data[[i]],src,paste(def,'Layer geom:',class(p$layers[[i]]$geom)[1]),privacy,complete,selector=paste0('ggplot_build(',name,')$data[[',i,']]'))
}
run('ED2_b',function(){src<-file.path(disco,'Result1/UKB.Clinical.DISCO2.rds');z<-readRDS(src)
 stopifnot(isTRUE(all.equal(z$en,readRDS(file.path(disco,'Result1/En.UKB2.rds')))),isTRUE(all.equal(z$hd,readRDS(file.path(disco,'Result1/HD.UKB2.rds')))))
 private_points('ED2_b','actual_DISCO2_DM_entropy_points',z[,c('hd','en')],src,'ActualED2b originalproducer input DISCO2 NOTDISCO; verifiedsavedentropy+HDvectors identical; restrictedindividualpoints.')
 emit('ED2_b','Spearman_annotation',cor(log(z$hd),z$en,method='spearman',use='complete.obs'),src,'ActualSpearman(logDM,Entropy) regeneratedannotation; no PDFvalueinference.',complete=FALSE)})
run('ED2_c',function(){src<-file.path(disco,'Result2/UKB.ClinicalProt.DISCO.rds');z<-readRDS(src);z$en<-readRDS(file.path(disco,'Result2/En.UKB2.rds'));stopifnot(nrow(z)==length(z$en))
