run('ED4_a',function(){src<-file.path(disco,'Result1/DNAm/Cmp_with_other.R');e<-ctx();e$MC<-readRDS(file.path(disco,'Result1/NHANES.Clinical.DISCO2.rds'));e$MC$raw<-exp(e$MC$mc)
