run('Fig3_b_age',function(){src<-file.path(disco,'Result1/DNAm/Cmp_with_other.R');e<-ctx();e$DNAm1<-readRDS(file.path(disco,'Result1/DNAm/NHANES.DNAm.res.rds'));e$DNAm1<-e$DNAm1[!is.na(e$DNAm1$HorvathAge),];block(src,241,285,e)
