 plotlayers('ED8_c',paste0('wave_',w,'_violin_box_and_test'),e$.last_plot,src,'Actualoriginalgeom_violin,boxplot anddefaultWilcoxoncomparemeans; builtin density/boxstats/pannotation; outlierlist containsindividual values so restricted below.',privacy='private_participant')
 b<-ggplot_build(e$.last_plot)
 emit('ED8_c',paste0('wave_',w,'_violin_density'),b$data[[1]],src,'Actualdensityaggregateviolin coordinates; noindividualoutliers.',selector='ggplot_build(originalplot)$data[[1]]')
 box<-b$data[[2]];box$outliers<-NULL;emit('ED8_c',paste0('wave_',w,'_boxplot_summary'),box,src,'Boxsummaryaggregatewhiskers/quartiles; individualoutliers deliberatelyremoved.',selector='ggplot_build(originalplot)$data[[2]] excludingoutliers')
 emit('ED8_c',paste0('wave_',w,'_comparison_annotations'),b$data[[3]],src,'ActualdefaultWilcoxonbracketannotations; multiplecomparisonadjustment notassumed.',selector='ggplot_build(originalplot)$data[[3]]')
}})
